        <div className="space-y-1">
          <p className="text-[13px] text-muted">
            {PRIORITY_LABELS[item.priority]}
            {item.qty > 1 && `, register for ${item.qty}`}
          </p>
          <h2 className="font-serif text-[26px] leading-tight font-semibold">{item.name}</h2>
        </div>

        <p className="font-serif text-[17px] leading-relaxed text-note italic">{item.reason}</p>

        {primary && (
          <a
            href={primary.url}
            target="_blank"
            rel="noopener noreferrer sponsored"
            className="flex items-center justify-between gap-4 rounded-xl border border-line px-4 py-3 transition-colors hover:bg-raise"
          >
            <span className="min-w-0">
              <span className="line-clamp-2 text-[14px] leading-snug">{primary.title}</span>
              <span className="text-[13px] text-muted">{RETAILER_LABELS[primary.retailer]}</span>
            </span>
            <span className="shrink-0 text-[17px] font-semibold tabular-nums">{formatPrice(primary.price)}</span>
          </a>
        )}

        {onChooseOffer && alternatives.length > 0 && (
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-[13px] text-muted">Switch to</span>
            {alternatives.map((offer) => (
              <button key={offer.id} className="chip text-[13px]" onClick={() => onChooseOffer(offer.id)}>
                {offer.price === null
                  ? RETAILER_LABELS[offer.retailer]
                  : `${formatPrice(offer.price)} at ${RETAILER_LABELS[offer.retailer]}`}
              </button>
            ))}
          </div>
        )}

        {children}
      </div>
    </article>
  );
}

